// Aliases seen in payloads (derive.js PLAT_KEY / provider column).
const ALIAS = { twitter: 'x', bsky: 'bluesky', li: 'linkedin', bs: 'bluesky', ig: 'instagram', fb: 'facebook' };

export function brandKey(name) {
  const k = String(name ?? '').toLowerCase();
  return ALIAS[k] ?? k;
}

export function brandTitle(name) {
  const k = brandKey(name);
  return BRAND[k]?.title ?? GENERIC[k]?.title ?? (name ? String(name) : '');
}

/** <BrandIcon name="linkedin" size={14}/> — monochrome mark; `tint` paints it
 *  in the brand colour (selected / hover states). Unknown names → null. */
export function BrandIcon({ name, size = 14, tint = false, className = '', label }) {
  const k = brandKey(name);
  const b = BRAND[k];
  const title = label ?? brandTitle(k);
  if (b) {
    // Near-black marks (X, Resend, Buffer) would vanish on dark themes — they
    // keep the text colour even when tinted.
    const dark = parseInt(b.hex.slice(1), 16) < 0x333333;
    const fill = tint && !dark ? b.hex : 'currentColor';
    return html`<svg class=${'brand-ico ' + className} data-brand=${k} width=${size} height=${size}
      viewBox="0 0 24 24" fill=${fill} role="img" aria-label=${title}
      style=${{ '--brand': b.hex }}><title>${title}</title><path d=${b.d} /></svg>`;
  }
  const g = GENERIC[k];
  if (!g) return null;
  return html`<svg class=${'brand-ico is-generic ' + className} data-brand=${k} width=${size} height=${size}
    viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
    stroke-linejoin="round" role="img" aria-label=${title}><title>${title}</title><path d=${g.d} /></svg>`;
}
